-- 25 Nov 2026 library update: final MPG-2026 (Ministry of Coal, 20 Nov 2026) and the three Ministry of Coal orders
-- under the MMDR penalty regime (s.25B adjudicating officer, s.25C appellate authority, Adjudication Rules r.3 complainant).
-- Rows generated from src/data/regulations-full-seed.json; hosted PDFs were uploaded first.
begin;
insert into public.regulations (slug,title,category,summary,doc_number,authority,issued_date,status,status_note,source_url,source_filename,relevance,sort_order,published,featured) values
('moc-mining-plan-mine-closure-guidelines-2026','Guidelines for preparation of Mining Plan and Mine Closure Plan for Coal and Lignite Mines, 2026 (MPG-2026)','moc','Issued by the Ministry of Coal by Office Memorandum of 20 November 2026, after the July 2026 draft, these guidelines replace MPG-2025 and all earlier mining plan and mine closure guidelines for coal and lignite. Every block needs a Mining Plan approved by the Coal Controller, valid for the life of the mine or 30 years, whichever is earlier; a public-sector company''s Board may approve the plan where the land was acquired under the Coal Bearing Areas Act, 1957 or the coal nationalisation Acts and CMPDIL prepared or vetted it. Plans must be prepared by a qualified person or accredited Mining Plan Preparing Agency and carry a ₹1 lakh fee; a Technical Committee scrutinises them on fixed timelines. The Mine Closure Plan is part of the Mining Plan: a post-mining closure period of three years and two years of monitoring follow production. Before mining starts the proponent opens an escrow account under a tripartite agreement with the Coal Controller''s Organisation and deposits each year ₹2 lakh per hectare for underground mines (₹14 lakh for opencast), at May 2024 rates indexed to WPI and escalated 5% a year; the plan is suspended if a deposit is not made by 31 December of the next financial year, and can be withdrawn six months later. Using land outside the block needs a State Government NOC (Appendix I). The UCG mining plan guidelines of 2026 form part of these guidelines.','F.No. CPAM-34011/28/2019-CPAM-Part(1)','Ministry of Coal','2026-11-20','notified','Comes into force 30 days from issue (20 Dec 2026). Mining Plans uploaded on the SWCS portal before then stay under MPG-2025; plans approved under earlier guidelines are deemed approved under these.','https://coal.nic.in/sites/default/files/2026-11/23-11-2026d-wn.pdf','MPG_2026_MiningPlan_MineClosure_Guidelines_FINAL_20112026.pdf',1,69,true,false),
('moc-mmdr-s25b-adjudicating-officer-order-2026','Ministry of Coal Order No. 22/2/2014-ASO — Adjudicating Officer for Coal and Lignite under Section 25B(1), MMDR Act','moc','Order of 20 November 2026 appointing the Deputy Coal Controller, Coal Controller''s Organisation, as the Central Government''s adjudicating officer for coal and lignite under section 25B(1) of the MMDR Act, 1957: the officer who decides penalties under section 25A for contraventions of the rules on mining plans and mine closure plans, on reports to the Coal Controller''s Organisation or the Indian Bureau of Mines, and on other Central Government functions. In force from the date of issue.','No. 22/2/2014-ASO','Ministry of Coal','2026-11-20','in_force',null,'https://coal.nic.in/sites/default/files/2026-11/23-11-2026a-wn.pdf','MoC_MMDR_s25B_AdjudicatingOfficer_23112026.pdf',2,77,true,false),
('moc-mmdr-s25c-appellate-authority-order-2026','Ministry of Coal Order No. 22/2/2014-ASO — Appellate Authority for Coal and Lignite under Section 25C(1), MMDR Act','moc','Order of 20 November 2026 appointing the Coal Controller as the appellate authority, for coal and lignite, for appeals against orders of the adjudicating officer appointed under section 25B(1) of the MMDR Act, 1957. Under section 25C an appeal lies within 30 days, with 10% of the penalty deposited. In force from the date of issue.','No. 22/2/2014-ASO','Ministry of Coal','2026-11-20','in_force',null,'https://coal.nic.in/sites/default/files/2026-11/23-11-2026c-wn.pdf','MoC_MMDR_s25C_AppellateAuthority_23112026.pdf',2,78,true,false),
('moc-adjudication-penalties-rule-3-gazetted-officer-order-2026','Ministry of Coal Order No. 22/2/2014-ASO — Gazetted Officer authorised to file complaints under Rule 3, Mines and Minerals Adjudication of Penalties Rules, 2026','moc','Order of 19 November 2026 authorising a Coal Superintendent of the Coal Controller''s Organisation as the gazetted officer who, for coal and lignite, files complaints of contraventions with the adjudicating officer appointed under section 25B(1) of the MMDR Act, under rule 3 of the Mines and Minerals Adjudication of Penalties Rules, 2026. In force from the date of issue.','No. 22/2/2014-ASO','Ministry of Coal','2026-11-19','in_force',null,'https://coal.nic.in/sites/default/files/2026-11/23-11-2026b-wn.pdf','MoC_MMAdjudication_r3_GazettedOfficer_23112026.pdf',2,79,true,false)
on conflict (slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,doc_number=excluded.doc_number,authority=excluded.authority,issued_date=excluded.issued_date,status=excluded.status,status_note=excluded.status_note,source_url=excluded.source_url,source_filename=excluded.source_filename,relevance=excluded.relevance,sort_order=excluded.sort_order,published=excluded.published,featured=excluded.featured;
