update public.regulations set status_note='Falls away with MPG-2025 when MPG-2026 comes into force on 20 Dec 2026.' where slug='moc-mpg-2025-corrigendum';
update public.regulations set status_note='In force from 1 Aug 2026. For coal and lignite, the Ministry of Coal named the complaining officer (19 Nov 2026), the adjudicating officer and the appellate authority (20 Nov 2026), all in the Coal Controller’s Organisation; the three orders are listed separately.' where slug='mines-minerals-adjudication-of-penalties-rules-2026';
update public.regulations set download_url='https://docs.mangalamcoal.com/regs/moc-mining-plan-mine-closure-guidelines-2026.pdf', file_size_kb=862 where slug='moc-mining-plan-mine-closure-guidelines-2026';
update public.regulations set download_url='https://docs.mangalamcoal.com/regs/moc-mmdr-s25b-adjudicating-officer-order-2026.pdf', file_size_kb=285 where slug='moc-mmdr-s25b-adjudicating-officer-order-2026';
update public.regulations set download_url='https://docs.mangalamcoal.com/regs/moc-mmdr-s25c-appellate-authority-order-2026.pdf', file_size_kb=251 where slug='moc-mmdr-s25c-appellate-authority-order-2026';
update public.regulations set download_url='https://docs.mangalamcoal.com/regs/moc-adjudication-penalties-rule-3-gazetted-officer-order-2026.pdf', file_size_kb=309 where slug='moc-adjudication-penalties-rule-3-gazetted-officer-order-2026';
